// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"runtime/debug"
	"slices"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown or Stop has been called.
var ErrStopped = errors.New("the job runner is stopped")

// stopTimeout is how long Stop waits for running jobs before canceling them.
const stopTimeout = 30 * time.Second

// entry is a job with its enqueue order, so Pending can list jobs in that order.
type entry struct {
	seq int
	job Job
}

// Runner runs jobs on its workers.
type Runner struct {
	workers  int
	capacity int
	log      *slog.Logger

	// jobCtx is passed to every job; Shutdown cancels it to interrupt running jobs.
	jobCtx     context.Context
	cancelJobs context.CancelFunc

	wg      sync.WaitGroup // workers
	stopped chan struct{}  // closed when the first Shutdown call has finished

	mu          sync.Mutex
	cond        *sync.Cond
	started     bool
	stopping    bool
	seq         int
	queue       []entry // waiting jobs, in enqueue order
	interrupted []entry // jobs that Shutdown canceled and that returned an error
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	jobCtx, cancelJobs := context.WithCancel(context.Background())
	r := &Runner{
		workers:    workers,
		capacity:   queueSize,
		log:        log,
		jobCtx:     jobCtx,
		cancelJobs: cancelJobs,
		stopped:    make(chan struct{}),
	}
	r.cond = sync.NewCond(&r.mu)
	return r
}

// Start starts the workers. It does nothing after Shutdown.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.started || r.stopping {
		return
	}
	r.started = true
	r.wg.Add(r.workers)
	for i := 0; i < r.workers; i++ {
		go r.work()
	}
}

func (r *Runner) work() {
	defer r.wg.Done()
	for {
		e, ok := r.next()
		if !ok {
			return
		}
		if r.run(e) {
			r.mu.Lock()
			r.interrupted = append(r.interrupted, e)
			r.mu.Unlock()
		}
	}
}

// next waits for a queued job and takes it off the queue. It returns false once the runner is stopping,
// leaving the jobs that have not started in the queue.
func (r *Runner) next() (entry, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for len(r.queue) == 0 && !r.stopping {
		r.cond.Wait()
	}
	if r.stopping {
		return entry{}, false
	}
	e := r.queue[0]
	r.queue[0] = entry{}
	r.queue = r.queue[1:]
	return e, true
}

// run runs one job and recovers a panic, which is logged and not retried. It reports whether Shutdown
// canceled the job and the job returned an error.
func (r *Runner) run(e entry) (interrupted bool) {
	var err error
	panicked := true
	func() {
		defer func() {
			if p := recover(); p != nil {
				r.log.Error("job panicked", "job", e.job.Name, "panic", p, "stack", string(debug.Stack()))
				return
			}
			panicked = false
		}()
		err = e.job.Run(r.jobCtx)
	}()
	if panicked || err == nil {
		return false
	}
	r.log.Error("job failed", "job", e.job.Name, "err", err)
	return r.jobCtx.Err() != nil
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
