// waitStopping waits until Shutdown has started, so a test can release a job knowing the runner is stopping.
func waitStopping(t *testing.T, r *Runner) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for {
		r.mu.Lock()
		stopping := r.stopping
		r.mu.Unlock()
		if stopping {
			return
		}
		if time.Now().After(deadline) {
			t.Fatal("Shutdown did not start")
		}
		time.Sleep(time.Millisecond)
	}
}

func TestEnqueueAfterShutdown(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	job := Job{Name: "late", Run: func(context.Context) error { t.Error("job ran after Shutdown"); return nil }}
	if err := r.Enqueue(job); !errors.Is(err, ErrStopped) {
		t.Fatalf("err = %v, want ErrStopped", err)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("pending = %v, want none", names(got))
	}
}

func TestShutdownLeavesUnstartedJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	started := make(chan struct{})
	release := make(chan struct{})
	var mu sync.Mutex
	var ran []string
	record := func(name string) func(context.Context) error {
		return func(context.Context) error {
			mu.Lock()
			defer mu.Unlock()
			ran = append(ran, name)
			return nil
		}
	}
	r.Enqueue(Job{Name: "a", Run: func(context.Context) error { close(started); <-release; return nil }})
	r.Enqueue(Job{Name: "b", Run: record("b")})
	r.Enqueue(Job{Name: "c", Run: record("c")})
	r.Start()
	<-started

	done := make(chan error)
	go func() { done <- r.Shutdown(context.Background()) }()
	waitStopping(t, r)
	close(release)
	if err := <-done; err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
	if len(ran) != 0 {
		t.Fatalf("ran = %v, want no queued jobs started", ran)
	}
	if got := names(r.Pending()); !slices.Equal(got, []string{"b", "c"}) {
		t.Fatalf("pending = %v, want [b c]", got)
	}
}

func TestShutdownWaitsForRunningJobs(t *testing.T) {
	r := NewRunner(2, 10, nil)
	started := make(chan struct{})
	release := make(chan struct{})
	var finished atomic.Bool
	r.Enqueue(Job{Name: "a", Run: func(context.Context) error {
		close(started)
		<-release
		finished.Store(true)
		return nil
	}})
	r.Start()
	<-started

	done := make(chan error)
	go func() { done <- r.Shutdown(context.Background()) }()
	waitStopping(t, r)
	close(release)
	if err := <-done; err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
	if !finished.Load() {
		t.Fatal("Shutdown returned before the running job finished")
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("pending = %v, want none", names(got))
	}
}

func TestShutdownCancelsRunningJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	started := make(chan struct{})
	noop := func(context.Context) error { return nil }
	r.Enqueue(Job{Name: "slow", Run: func(ctx context.Context) error {
		close(started)
		<-ctx.Done()
		return ctx.Err()
	}})
	r.Enqueue(Job{Name: "b", Run: noop})
	r.Enqueue(Job{Name: "c", Run: noop})
	r.Start()
	<-started

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want DeadlineExceeded", err)
	}
	// Jobs that never started come first, then the canceled job that returned an error.
	if got := names(r.Pending()); !slices.Equal(got, []string{"b", "c", "slow"}) {
		t.Fatalf("pending = %v, want [b c slow]", got)
	}
}

