// savePending writes the names of the jobs that did not run to path, so the next start queues them again.
// With no pending jobs it removes path.
func savePending(path string, pending []jobs.Job) error {
	if len(pending) == 0 {
		if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
		return nil
	}
	names := make([]string, 0, len(pending))
	for _, j := range pending {
		names = append(names, j.Name)
	}
	b, err := json.Marshal(names)
	if err != nil {
		return err
	}
	return os.WriteFile(path, b, 0o644)
}

// loadPending returns the job names saved by savePending and removes path. A missing file means no jobs.
func loadPending(path string) ([]string, error) {
	b, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var names []string
	if err := json.Unmarshal(b, &names); err != nil {
		return nil, err
	}
	return names, os.Remove(path)
}

