package main

import (
	"context"
	"os"
	"path/filepath"
	"slices"
	"testing"

	"example.com/tally/internal/jobs"
)

func TestPendingRoundTrip(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tally.json.pending")
	noop := func(context.Context) error { return nil }
	pending := []jobs.Job{{Name: "renewals", Run: noop}, {Name: "webhooks", Run: noop}}
	if err := savePending(path, pending); err != nil {
		t.Fatal(err)
	}
	names, err := loadPending(path)
	if err != nil {
		t.Fatal(err)
	}
	if !slices.Equal(names, []string{"renewals", "webhooks"}) {
		t.Fatalf("names = %v, want [renewals webhooks]", names)
	}
	if _, err := os.Stat(path); !os.IsNotExist(err) {
		t.Fatalf("pending file still exists after load: %v", err)
	}
}

func TestSavePendingWithNoJobsRemovesFile(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tally.json.pending")
	if err := os.WriteFile(path, []byte(`["renewals"]`), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := savePending(path, nil); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(path); !os.IsNotExist(err) {
		t.Fatalf("pending file exists, want it removed: %v", err)
	}
}

func TestLoadPendingMissingFile(t *testing.T) {
	names, err := loadPending(filepath.Join(t.TempDir(), "none"))
	if err != nil || names != nil {
		t.Fatalf("loadPending = %v, %v; want nil, nil", names, err)
	}
}
