package jobs

import (
	"context"
	"errors"
	"slices"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func TestRunnerRunsJobs(t *testing.T) {
	r := NewRunner(3, 10, nil)
	r.Start()
	var mu sync.Mutex
	done := map[string]bool{}
	var wg sync.WaitGroup
	for _, name := range []string{"a", "b", "c", "d", "e"} {
		wg.Add(1)
		if err := r.Enqueue(Job{Name: name, Run: func(ctx context.Context) error {
			defer wg.Done()
			mu.Lock()
			done[name] = true
			mu.Unlock()
			return nil
		}}); err != nil {
			t.Fatal(err)
		}
	}
	finished := make(chan struct{})
	go func() { wg.Wait(); close(finished) }()
	select {
	case <-finished:
	case <-time.After(5 * time.Second):
		t.Fatal("jobs did not run")
	}
	if len(done) != 5 {
		t.Fatalf("done = %v", done)
	}
}

func TestEnqueueWhenFull(t *testing.T) {
	r := NewRunner(1, 1, nil) // not started: nothing takes jobs off the queue
	job := Job{Name: "x", Run: func(context.Context) error { return nil }}
	if err := r.Enqueue(job); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(job); !errors.Is(err, ErrQueueFull) {
		t.Fatalf("err = %v, want ErrQueueFull", err)
	}
}

func names(jobs []Job) []string {
	var out []string
	for _, j := range jobs {
		out = append(out, j.Name)
	}
	return out
}

// waitStopping waits until Shutdown has started, so a test can release a job knowing the runner is stopping.
func waitStopping(t *testing.T, r *Runner) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for {
		r.mu.Lock()
		stopping := r.stopping
		r.mu.Unlock()
		if stopping {
			return
		}
		if time.Now().After(deadline) {
			t.Fatal("Shutdown did not start")
		}
		time.Sleep(time.Millisecond)
	}
}

func TestEnqueueAfterShutdown(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	job := Job{Name: "late", Run: func(context.Context) error { t.Error("job ran after Shutdown"); return nil }}
	if err := r.Enqueue(job); !errors.Is(err, ErrStopped) {
		t.Fatalf("err = %v, want ErrStopped", err)
	}
	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("pending = %v, want none", names(got))
	}
}

func TestShutdownLeavesUnstartedJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	started := make(chan struct{})
	release := make(chan struct{})
	var mu sync.Mutex
	var ran []string
	record := func(name string) func(context.Context) error {
		return func(context.Context) error {
			mu.Lock()
			defer mu.Unlock()
			ran = append(ran, name)
			return nil
		}
	}
	r.Enqueue(Job{Name: "a", Run: func(context.Context) error { close(started); <-release; return nil }})
