	return r.jobCtx.Err() != nil
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped once Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.stopping {
		return ErrStopped
	}
	if len(r.queue) >= r.capacity {
		return ErrQueueFull
	}
	r.seq++
	r.queue = append(r.queue, entry{seq: r.seq, job: j})
	r.cond.Signal()
	return nil
}

// Shutdown stops the runner. Jobs that have not started are not started. It waits for running jobs to
// finish; if ctx ends first, it cancels their contexts, waits for them to return, and returns ctx.Err().
// Calls after the first return nil at once, without waiting for the first call.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.stopping {
		r.mu.Unlock()
		return nil
	}
	r.stopping = true
	r.cond.Broadcast()
	r.mu.Unlock()

	workersDone := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(workersDone)
	}()
	select {
	case <-workersDone:
		r.cancelJobs()
		return nil
	case <-ctx.Done():
	}
	r.cancelJobs()
	<-workersDone
	return ctx.Err()
}

// Stop stops the runner, waiting up to 30 seconds for running jobs before canceling them.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in enqueue order. Before Shutdown these are the queued
// jobs. After Shutdown they are the jobs that never started, followed by the jobs that Shutdown canceled
// and that returned an error.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	interrupted := slices.Clone(r.interrupted)
	slices.SortFunc(interrupted, func(a, b entry) int { return a.seq - b.seq })
	var jobs []Job
	for _, e := range r.queue {
		jobs = append(jobs, e.job)
	}
	for _, e := range interrupted {
		jobs = append(jobs, e.job)
	}
	return jobs
}
// Command tally runs the Tally API with the demo payment gateway, keeping its data in a snapshot file.
//
//	tally -addr :8080 -data tally.json
package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"example.com/tally/internal/api"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/jobs"
	"example.com/tally/internal/mail"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/snapshot"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
	"example.com/tally/internal/webhooks"
)

func main() {
	addr := flag.String("addr", ":8080", "address to listen on")
	data := flag.String("data", "tally.json", "snapshot file (created when missing)")
	flag.Parse()
	log := slog.New(slog.NewTextHandler(os.Stderr, nil))
	clk := clock.Real{}

	st, err := snapshot.Load(*data)
	switch {
	case errors.Is(err, os.ErrNotExist):
		st = store.New()
		if err := seed(st, clk.Now(), log); err != nil {
			log.Error("seed", "err", err)
			os.Exit(1)
		}
	case err != nil:
		log.Error("load snapshot", "err", err)
		os.Exit(1)
	}

	hooks := webhooks.New(webhooks.Options{Store: st, Clock: clk})
	pay := &payments.Service{Store: st, Gateway: &payments.Fake{}, Clock: clk, Publisher: hooks}
	subs := &subscriptions.Service{Store: st, Payments: pay, Clock: clk, Publisher: hooks}
	srv := api.New(st, api.Options{Clock: clk, Payments: pay, Subscriptions: subs, Webhooks: hooks, Mail: &mail.Outbox{Log: log}, Logger: log})

	// runFor maps each job name to its work. The pending file stores names only, because Job.Run is a func.
	runFor := map[string]func(context.Context) error{
		"renewals": func(ctx context.Context) error { _, err := subs.RenewDue(ctx); return err },
		"webhooks": func(ctx context.Context) error { _, err := hooks.RunDue(ctx); return err },
	}
	runner := jobs.NewRunner(4, 100, log)
	pendingPath := *data + ".pending"
	saved, err := loadPending(pendingPath)
	if err != nil {
		log.Error("load pending jobs", "err", err)
	}
	for _, name := range saved {
		run, ok := runFor[name]
		if !ok {
			log.Warn("unknown pending job dropped", "job", name)
			continue
		}
		_ = runner.Enqueue(jobs.Job{Name: name, Run: run})
	}
	runner.Start()
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	go func() {
		t := time.NewTicker(30 * time.Second)
		defer t.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-t.C:
				for _, name := range []string{"renewals", "webhooks"} {
					_ = runner.Enqueue(jobs.Job{Name: name, Run: runFor[name]})
				}
			}
		}
	}()

	hs := &http.Server{Addr: *addr, Handler: srv, ReadHeaderTimeout: 10 * time.Second}
	go func() {
		log.Info("listening", "addr", *addr)
		if err := hs.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Error("serve", "err", err)
			stop()
		}
	}()
	<-ctx.Done()
	shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_ = hs.Shutdown(shutdown)
	if err := runner.Shutdown(shutdown); err != nil {
		log.Error("stop jobs", "err", err)
	}
	if err := savePending(pendingPath, runner.Pending()); err != nil {
		log.Error("save pending jobs", "err", err)
	}
	if err := snapshot.Save(st, *data, clk.Now()); err != nil {
		log.Error("save snapshot", "err", err)
		os.Exit(1)
	}
}

// savePending writes the names of the jobs that did not run to path, so the next start queues them again.
// With no pending jobs it removes path.
func savePending(path string, pending []jobs.Job) error {
	if len(pending) == 0 {
		if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
		return nil
	}
	names := make([]string, 0, len(pending))
	for _, j := range pending {
		names = append(names, j.Name)
	}
	b, err := json.Marshal(names)
	if err != nil {
		return err
	}
	return os.WriteFile(path, b, 0o644)
}

// loadPending returns the job names saved by savePending and removes path. A missing file means no jobs.
func loadPending(path string) ([]string, error) {
	b, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var names []string
	if err := json.Unmarshal(b, &names); err != nil {
		return nil, err
	}
	return names, os.Remove(path)
}

// seed adds a demo organization with an owner and prints the owner's API key.
func seed(st *store.Store, now time.Time, log *slog.Logger) error {
	o, err := st.CreateOrg("Demo Co", store.OrgTeam, "UTC", 0, now)
	if err != nil {
		return err
	}
	u, err := st.CreateUser("owner@demo.example", "Demo Owner", now)
	if err != nil {
		return err
	}
	if _, err := st.AddMember(o.ID, u.ID, store.RoleOwner, now); err != nil {
		return err
	}
	k, err := st.CreateAPIKey(o.ID, u.ID, "Demo key", now)
	if err != nil {
		return err
	}
	log.Info("demo organization created", "org", o.ID, "api_key", k.Token)
	return nil
}

