func TestShutdownAgainReturnsWhileJobRuns(t *testing.T) {
	r := NewRunner(1, 10, nil)
	started := make(chan struct{})
	release := make(chan struct{})
	r.Enqueue(Job{Name: "a", Run: func(context.Context) error {
		close(started)
		<-release
		return nil
	}})
	r.Start()
	<-started

	done := make(chan error)
	go func() { done <- r.Shutdown(context.Background()) }()
	waitStopping(t, r)

	// The job is still running, so the first call has not finished. Later calls must not wait for it,
	// even when their context has already ended.
	expired, cancel := context.WithCancel(context.Background())
	cancel()
	again := make(chan error)
	go func() { again <- r.Shutdown(expired) }()
	select {
	case err := <-again:
		if err != nil {
			t.Fatalf("second Shutdown = %v, want nil", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("second Shutdown waited for the running job")
	}

	stop := make(chan struct{})
	go func() { r.Stop(); close(stop) }()
	select {
	case <-stop:
	case <-time.After(5 * time.Second):
		t.Fatal("Stop after Shutdown waited for the running job")
	}

	close(release)
	if err := <-done; err != nil {
		t.Fatalf("first Shutdown = %v, want nil", err)
	}
}

