// A shutdown saves at most queueSize waiting jobs plus one interrupted job per worker. The queue has
// room for all of them, so a restart queues every saved job.
const workers, queueSize = 4, 100
runner := jobs.NewRunner(workers, queueSize+workers, log)
pendingPath := *data + ".pending"
saved, err := loadPending(pendingPath)
if err != nil {
	log.Error("load pending jobs", "err", err)
}
for _, name := range saved {
	run, ok := runFor[name]
	if !ok {
		log.Warn("unknown pending job dropped", "job", name)
		continue
	}
	if err := runner.Enqueue(jobs.Job{Name: name, Run: run}); err != nil {
		log.Error("requeue pending job dropped", "job", name, "err", err)
	}
}

